// Host adapter used by the executable simulator. Native implementations are
// provided by the app shell. A lease owns ongoing execution and its indicator.
export function createRuntime({ failConnect = false } = {}) {
  let background = false;
  const leases = new Set();
  const sessions = new Set();
  return {
    execution: {
      async acquire(reason) {
        const lease = { reason };
        leases.add(lease);
        return { async release() { leases.delete(lease); } };
      },
    },
    transport: {
      async connect(peerId) {
        if (failConnect) throw new Error('Connection failed');
        const session = { peerId, muted: false };
        sessions.add(session);
        return {
          async setMuted(value) { session.muted = value; },
          async disconnect() { sessions.delete(session); },
        };
      },
    },
    enterBackground() { background = true; },
    snapshot() {
      return {
        sessions: sessions.size,
        leases: leases.size,
        audible: sessions.size > 0 && (!background || leases.size > 0),
        muted: [...sessions].map(session => session.muted),
      };
    },
  };
}

