import test from 'node:test';
import assert from 'node:assert/strict';
import { createApp } from '../src/app.js';
import { createRuntime } from '../src/platform/runtime.js';

test('outgoing call survives background, supports mute and releases resources', async () => {
  const runtime = createRuntime();
  const { calls } = createApp(runtime);
  await calls.start('peer');
  runtime.enterBackground();
  assert.deepEqual(runtime.snapshot(), { sessions: 1, leases: 1, audible: true, muted: [false] });
  await calls.setMuted(true);
  assert.deepEqual(runtime.snapshot().muted, [true]);
  await calls.setMuted(false);
  assert.deepEqual(runtime.snapshot().muted, [false]);
  await calls.end();
  await calls.end();
  assert.deepEqual(runtime.snapshot(), { sessions: 0, leases: 0, audible: false, muted: [] });
  await calls.start('next');
  await calls.end();
});

test('failed connection releases its execution lease and allows retry', async () => {
  const runtime = createRuntime({ failConnect: true });
  const { calls } = createApp(runtime);
  await assert.rejects(calls.start('peer'), /Connection failed/);
  assert.equal(runtime.snapshot().leases, 0);
  await assert.rejects(calls.start('peer'), /Connection failed/);
  assert.equal(runtime.snapshot().sessions, 0);
});

test('pending connection rejects overlap and hang-up cleans up after connection', async () => {
  const runtime = createRuntime();
  const connect = runtime.transport.connect;
  let resolveConnection;
  runtime.transport.connect = peer => new Promise(resolve => {
    resolveConnection = () => resolve(connect(peer));
  });
  const { calls } = createApp(runtime);
  const pending = calls.start('peer');
  await assert.rejects(calls.start('other'), /already/);
  const ending = calls.end();
  while (!resolveConnection) await Promise.resolve();
  resolveConnection();
  await pending;
  await ending;
  assert.equal(runtime.snapshot().sessions, 0);
  assert.equal(runtime.snapshot().leases, 0);
});

test('execution acquisition failure never connects and allows retry', async () => {
  const runtime = createRuntime();
  const acquire = runtime.execution.acquire;
  runtime.execution.acquire = async () => { throw new Error('Unavailable'); };
  const { calls } = createApp(runtime);
  await assert.rejects(calls.start('peer'), /Unavailable/);
  assert.equal(runtime.snapshot().sessions, 0);
  runtime.execution.acquire = acquire;
  await calls.start('peer');
  await calls.end();
});

test('mute failure does not prevent hang-up cleanup', async () => {
  const runtime = createRuntime();
  const connect = runtime.transport.connect;
  runtime.transport.connect = async peer => ({
    ...await connect(peer),
    async setMuted() { throw new Error('Mute failed'); },
  });
  const { calls } = createApp(runtime);
  await calls.start('peer');
  await assert.rejects(calls.setMuted(true), /Mute failed/);
  await calls.end();
  assert.equal(runtime.snapshot().leases, 0);
  assert.equal(runtime.snapshot().sessions, 0);
});

test('disconnect failure still releases indicator and can be retried', async () => {
  const runtime = createRuntime();
  const connect = runtime.transport.connect;
  let fail = true;
  runtime.transport.connect = async peer => {
    const session = await connect(peer);
    return {
      ...session,
      async disconnect() {
        if (fail) throw new Error('Disconnect failed');
        await session.disconnect();
      },
    };
  };
  const { calls } = createApp(runtime);
  await calls.start('peer');
  await assert.rejects(calls.end(), /cleanup failed/);
  assert.equal(runtime.snapshot().leases, 0);
  await assert.rejects(calls.start('other'), /already/);
  fail = false;
  await calls.end();
  assert.equal(runtime.snapshot().sessions, 0);
});

