export function createApp(runtime) {
  let current = null;
  let operations = Promise.resolve();

  function enqueue(operation) {
    const result = operations.then(operation);
    operations = result.catch(() => {});
    return result;
  }

  async function cleanup(call) {
    const errors = [];
    if (call.session) {
      try {
        await call.session.disconnect();
        call.session = null;
      } catch (error) { errors.push(error); }
    }
    if (call.lease) {
      try {
        await call.lease.release();
        call.lease = null;
      } catch (error) { errors.push(error); }
    }
    // Retain failed resources so a later end() can retry their cleanup.
    if (!call.session && !call.lease && current === call) current = null;
    if (errors.length) throw new AggregateError(errors, 'Call cleanup failed');
  }

  return {
    calls: {
      async start(peerId) {
        if (current) throw new Error('A call is already in progress');
        const call = { session: null, lease: null, ending: false };
        current = call;
        return enqueue(async () => {
          try {
            call.lease = await runtime.execution.acquire('voice-call');
            call.session = await runtime.transport.connect(peerId);
          } catch (error) {
            try {
              await cleanup(call);
            } catch (cleanupError) {
              throw new AggregateError([error, cleanupError], 'Call start and cleanup failed');
            }
            throw error;
          }
        });
      },
      async setMuted(value) {
        if (typeof value !== 'boolean') throw new TypeError('Muted must be a boolean');
        const call = current;
        if (!call || call.ending) throw new Error('No active call');
        return enqueue(async () => {
          if (!call.session) throw new Error('No active call');
          await call.session.setMuted(value);
        });
      },
      async end() {
        const call = current;
        if (!call) return;
        call.ending = true;
        return enqueue(() => cleanup(call));
      },
    },
  };
}
